/*
 * SPDX-FileCopyrightText: 2026 ObiWindu <Obi.windu@proton.me>
 * SPDX-License-Identifier: LGPL-2.1-or-later
 *
 * Drives a real AgentLoop against the mock LLM endpoint so the suggest tool's
 * arguments are followed the whole way from the provider's stream to the
 * PermissionRequest the UI builds its card from.
 */

#include "agentloop.h"
#include "test_python.h"
#include "types.h"

#include <QCoreApplication>
#include <QDir>
#include <QElapsedTimer>
#include <QEventLoop>
#include <QFile>
#include <QFileInfo>
#include <QNetworkProxyFactory>
#include <QProcess>
#include <QTemporaryDir>
#include <QTest>
#include <memory>

using namespace Qt::Literals::StringLiterals;
using namespace KateAi;

class TestSuggestFlow : public QObject
{
    Q_OBJECT

private:
    static QString repoFile(const QString &relativePath)
    {
        QDir dir(QDir::current());
        for (int i = 0; i < 5; ++i) {
            const QString candidate = dir.absoluteFilePath(relativePath);
            if (QFileInfo::exists(candidate)) {
                return candidate;
            }
            dir.cdUp();
        }
        return {};
    }

    template<typename Predicate>
    static bool waitFor(Predicate predicate, int timeoutMs = 20000)
    {
        QElapsedTimer timer;
        timer.start();
        while (!predicate()) {
            if (timer.elapsed() > timeoutMs) {
                return false;
            }
            QCoreApplication::processEvents(QEventLoop::AllEvents, 20);
            QTest::qWait(10);
        }
        return true;
    }

    std::unique_ptr<QTemporaryDir> m_workspace;
    QProcess *m_server = nullptr;
    QString m_portFile;
    int m_port = 0;

private Q_SLOTS:
    void initTestCase()
    {
        QNetworkProxyFactory::setUseSystemConfiguration(false);
    }

    void init()
    {
        m_workspace = std::make_unique<QTemporaryDir>();
        QVERIFY(m_workspace->isValid());
        QFile marker(m_workspace->path() + u"/README.md"_s);
        QVERIFY(marker.open(QIODevice::WriteOnly | QIODevice::Text));
        marker.write("workspace\n");

        m_portFile = m_workspace->path() + u"/port"_s;
        m_server = new QProcess(this);
        const QString script = repoFile(u"tests/mock_llm_server.py"_s);
        QVERIFY2(!script.isEmpty(), "could not locate tests/mock_llm_server.py");
        m_server->start(python3Command(), QStringList{script, m_portFile});
        QVERIFY(m_server->waitForStarted(10000));

        QVERIFY(waitFor([this] {
            QFile f(m_portFile);
            if (!f.open(QIODevice::ReadOnly | QIODevice::Text)) {
                return false;
            }
            return QString::fromUtf8(f.readAll()).trimmed().toInt() > 0;
        }, 15000));
        QFile portFile(m_portFile);
        QVERIFY(portFile.open(QIODevice::ReadOnly | QIODevice::Text));
        m_port = QString::fromUtf8(portFile.readAll()).trimmed().toInt();
        QVERIFY(m_port > 0);
    }

    void cleanup()
    {
        if (m_server) {
            if (m_server->state() != QProcess::NotRunning) {
                m_server->kill();
                m_server->waitForFinished(5000);
            }
            delete m_server;
            m_server = nullptr;
        }
        m_workspace.reset();
    }

    // Runs one turn against the given provider and returns the request the
    // suggest tool call produced, so each shape a provider can stream it in
    // can be checked the same way. The provider picker keeps the settings
    // block readable; nullptr means "no call arrived".
    PermissionRequest suggestRequestFor(Provider provider, const QString &prompt, bool *arrived)
    {
        *arrived = false;
        AgentLoop agent;
        agent.setWorkspace(m_workspace->path());
        Settings settings;
        settings.provider = provider;
        settings.agentMode = u"code"_s;
        if (provider == Provider::ClaudeCompatible) {
            settings.claudeCompatibleUrl = u"http://127.0.0.1:%1"_s.arg(m_port);
            settings.claudeCompatibleApiKey = u"test"_s;
            settings.claudeCompatibleModel = u"mock"_s;
        } else {
            settings.openaiCompatibleUrl = u"http://127.0.0.1:%1/v1"_s.arg(m_port);
            settings.openaiCompatibleApiKey = u"test"_s;
            settings.openaiCompatibleModel = u"mock"_s;
        }
        agent.setSettings(settings);

        QList<PermissionRequest> started;
        connect(&agent, &AgentLoop::toolStarted, this, [&started](const PermissionRequest &request) {
            started.append(request);
        });

        agent.start(prompt);
        waitFor([&started] {
            return !started.isEmpty();
        });
        if (started.size() != 1) {
            return {};
        }
        const PermissionRequest request = started.first();
        if (request.toolName != u"suggest"_s) {
            return {};
        }
        *arrived = true;
        return request;
    }

    void argumentStringShapeKeepsTheAdvice()
    {
        bool arrived = false;
        const PermissionRequest request = suggestRequestFor(Provider::OpenAICompatible, u"Suggest an improvement."_s, &arrived);
        QVERIFY2(arrived, "no suggest call arrived");
        QVERIFY2(request.details.contains(u"std::string_view"_s), qPrintable(request.details));
        QVERIFY2(request.summary.contains(u"std::string_view"_s), qPrintable(request.summary));
    }

    void argumentObjectShapeKeepsTheAdvice()
    {
        // Ollama and other local servers send "arguments" as a JSON object
        // rather than a string; reading it as a string drops it entirely and
        // the call reaches the tool with an empty object.
        bool arrived = false;
        const PermissionRequest request = suggestRequestFor(Provider::OpenAICompatible, u"Suggest with object arguments."_s, &arrived);
        QVERIFY2(arrived, "no suggest call arrived");
        QVERIFY2(request.details.contains(u"std::string_view"_s), qPrintable(request.details));
        QVERIFY2(request.summary.contains(u"std::string_view"_s), qPrintable(request.summary));
    }

    void anthropicFragmentShapeKeepsTheAdvice()
    {
        bool arrived = false;
        const PermissionRequest request = suggestRequestFor(Provider::ClaudeCompatible, u"Suggest an improvement."_s, &arrived);
        QVERIFY2(arrived, "no suggest call arrived");
        QVERIFY2(request.details.contains(u"std::string_view"_s), qPrintable(request.details));
    }
};

QTEST_MAIN(TestSuggestFlow)
#include "test_suggestflow.moc"

# SPDX-FileCopyrightText: 2026 ObiWindu <Obi.wandu@proton.me>
# SPDX-License-Identifier: LGPL-2.1-or-later
#
# Build (when Craft/KF6 is available) and install kateai.dll for Kate on Windows.
#   powershell -ExecutionPolicy Bypass -File packaging/windows/install.ps1
#   powershell -ExecutionPolicy Bypass -File packaging/windows/install.ps1 -Uninstall
#   powershell -ExecutionPolicy Bypass -File packaging/windows/install.ps1 -KateDir "C:\Program Files\Kate"

[CmdletBinding()]
param(
    [switch] $User,
    [switch] $System,
    [switch] $Uninstall,
    [switch] $SkipTests,
    [string] $KateDir,
    [string] $BuildType = "Release"
)

$ErrorActionPreference = "Stop"
$Root = Resolve-Path (Join-Path $PSScriptRoot "..\..")
$PluginRel = "kf6\ktexteditor\kateai.dll"
$UserPluginDir = Join-Path $env:LOCALAPPDATA "KateAI\plugins"

function Find-KateRoot {
    if ($KateDir) {
        return (Resolve-Path $KateDir).Path
    }
    $candidates = @()
    if ($env:KDEROOT) { $candidates += $env:KDEROOT }
    $candidates += @(
        (Join-Path ${env:ProgramFiles} "Kate"),
        (Join-Path ${env:ProgramFiles} "KDE\Kate"),
        (Join-Path ${env:LOCALAPPDATA} "Programs\Kate")
    )
    $cmd = Get-Command kate.exe -ErrorAction SilentlyContinue
    if ($cmd) {
        $candidates += (Split-Path $cmd.Source -Parent)
        $candidates += (Split-Path (Split-Path $cmd.Source -Parent) -Parent)
    }
    foreach ($c in $candidates) {
        if (-not $c) { continue }
        $exe = Join-Path $c "bin\kate.exe"
        if (Test-Path $exe) { return $c }
        if (Test-Path (Join-Path $c "kate.exe")) { return $c }
    }
    return $null
}

function Find-KatePluginDir([string] $root) {
    if (-not $root) { return $null }
    $guesses = @(
        (Join-Path $root "bin\kf6\ktexteditor"),
        (Join-Path $root "kf6\ktexteditor"),
        (Join-Path $root "lib\plugins\kf6\ktexteditor"),
        (Join-Path $root "plugins\kf6\ktexteditor")
    )
    foreach ($g in $guesses) {
        if (Test-Path $g) { return $g }
    }
    $found = Get-ChildItem -Path $root -Recurse -Directory -Filter ktexteditor -ErrorAction SilentlyContinue |
        Where-Object { $_.FullName -match 'kf6' } |
        Select-Object -First 1
    if ($found) { return $found.FullName }
    return $guesses[0]
}

function Add-UserPluginPath([string] $dir) {
    $current = [Environment]::GetEnvironmentVariable("QT_PLUGIN_PATH", "User")
    if ([string]::IsNullOrEmpty($current)) {
        [Environment]::SetEnvironmentVariable("QT_PLUGIN_PATH", $dir, "User")
        return
    }
    $parts = $current -split ';' | Where-Object { $_ -and ($_ -ne $dir) }
    $joined = (@($dir) + $parts) -join ';'
    [Environment]::SetEnvironmentVariable("QT_PLUGIN_PATH", $joined, "User")
}

function Remove-UserPluginPath([string] $dir) {
    $current = [Environment]::GetEnvironmentVariable("QT_PLUGIN_PATH", "User")
    if ([string]::IsNullOrEmpty($current)) { return }
    $parts = $current -split ';' | Where-Object { $_ -and ($_ -ne $dir) }
    $joined = $parts -join ';'
    if ([string]::IsNullOrEmpty($joined)) {
        [Environment]::SetEnvironmentVariable("QT_PLUGIN_PATH", $null, "User")
    } else {
        [Environment]::SetEnvironmentVariable("QT_PLUGIN_PATH", $joined, "User")
    }
}

if ($Uninstall) {
    $removed = $false
    $kateRoot = Find-KateRoot
    $dirs = @((Join-Path $UserPluginDir "kf6\ktexteditor"))
    if ($kateRoot) { $dirs += (Find-KatePluginDir $kateRoot) }
    foreach ($d in $dirs) {
        $so = Join-Path $d "kateai.dll"
        if (Test-Path $so) {
            Remove-Item -Force $so
            Write-Host "Removed $so"
            $removed = $true
        }
    }
    Remove-UserPluginPath $UserPluginDir
    if (-not $removed) {
        Write-Error "Kate AI plugin not found in the usual plugin directories."
    }
    Write-Host "Fully quit Kate and reopen it so the plugin list refreshes."
    exit 0
}

$cmake = Get-Command cmake -ErrorAction SilentlyContinue
if (-not $cmake) {
    Write-Error @"
cmake was not found. On Windows, build Kate AI with KDE Craft so the plugin matches Kate:

  craft kateai

Copy packaging/craft/kateai.py into your Craft blueprints tree first.
Alternatively install Craft, enter the Craft shell, then re-run this script.
"@
}

$BuildDir = Join-Path $Root "build"
$configure = @(
    "-S", $Root, "-B", $BuildDir,
    "-DCMAKE_BUILD_TYPE=$BuildType"
)
if ($User -or -not $System) {
    $configure += "-DKATEAI_USER_INSTALL=ON"
} else {
    $configure += "-DKATEAI_USER_INSTALL=OFF"
    $configure += "-DKDE_INSTALL_USE_QT_SYS_PATHS=ON"
}

Write-Host "==> Configuring ($BuildType)"
& cmake @configure
Write-Host "==> Building"
& cmake --build $BuildDir --config $BuildType -j $env:NUMBER_OF_PROCESSORS
if (-not $SkipTests -and $env:SKIP_TESTS -ne "1") {
    Write-Host "==> Tests"
    & ctest --test-dir $BuildDir -C $BuildType --output-on-failure
}

$built = Get-ChildItem -Path $BuildDir -Recurse -Filter kateai.dll | Select-Object -First 1
if (-not $built) {
    Write-Error "Build did not produce kateai.dll under $BuildDir"
}

$kateRoot = Find-KateRoot
$destDir = $null
if ($System -and $kateRoot) {
    $destDir = Find-KatePluginDir $kateRoot
} elseif ($kateRoot -and -not $User) {
    $pluginDir = Find-KatePluginDir $kateRoot
    if ($pluginDir -and (Test-Path $pluginDir) -and (Get-Acl $pluginDir).Access) {
        $destDir = $pluginDir
    }
}
if (-not $destDir) {
    $destDir = Join-Path $UserPluginDir "kf6\ktexteditor"
}

New-Item -ItemType Directory -Force -Path $destDir | Out-Null
$dest = Join-Path $destDir "kateai.dll"
Copy-Item -Force $built.FullName $dest
Write-Host "Installed: $dest"

if ($destDir.StartsWith($UserPluginDir)) {
    Add-UserPluginPath $UserPluginDir
    Write-Host "User QT_PLUGIN_PATH now includes $UserPluginDir"
    Write-Host "Sign out or reboot so GUI Kate picks up the new plugin path, or start Kate from this session."
} else {
    Write-Host "Copied next to Kate. Fully quit Kate, then enable Kate AI under Settings → Plugins."
}

