        QByteArray openaiModelNotFound = "{\"error\":{\"type\":\"model_not_found\",\"message\":\"Model not found\"}}";
        QCOMPARE(client.classifyError(404, QString(), openaiModelNotFound, QNetworkReply::NoError),
