        QByteArray openaiInvalidKey = "{\"error\":{\"type\":\"invalid_api_key\",\"message\":\"Invalid key\"}}";
        QCOMPARE(client.classifyError(401, QString(), openaiInvalidKey, QNetworkReply::NoError),
