#!/usr/bin/env python3
"""Minimal ACP agent over stdio used by the Kate AI integration test.

Speaks initialize, session/new, session/prompt, session/cancel, and can issue
session/request_permission, fs/*, and terminal/* back to the client.
"""

import json
import sys
import time

SCENARIO = sys.argv[1] if len(sys.argv) > 1 else "echo"
NEXT_ID = 1000
SESSION_ID = "sess_kateai_test"
CURRENT_MODEL = "grok-4.5"
CURRENT_EFFORT = "medium"
PROMPT_COUNT = 0
TOOL_QUESTION_COUNT = 0
EFFORT_CONFIG_ID = "thinking" if SCENARIO == "mistral-thinking" else "thinking_level"


def model_config(current, extra=False):
    options = [
        {
            "group": "grok",
            "name": "Grok",
            "options": [
                {"name": "Grok 4", "value": "grok-4"},
                {"name": "Grok 4.5", "value": "grok-4.5"},
            ],
        }
    ]
    if extra:
        options[0]["options"].append({"name": "Grok 4.7", "value": "grok-4.7"})
    return {
        "id": "model",
        "name": "Model",
        "category": "model",
        "type": "select",
        "currentValue": current,
        "options": options,
    }


def mode_config():
    return {
        "id": "mode",
        "name": "Mode",
        "category": "mode",
        "type": "select",
        "currentValue": "code",
        "options": [{"name": "Code", "value": "code"}],
    }


def effort_config(current):
    if SCENARIO == "mistral-thinking":
        # Mistral's vibe-acp advertises its thinking level with the category
        # and id "thinking" instead of Zed's "thought_level" category.
        return {
            "id": "thinking",
            "name": "Thinking",
            "category": "thinking",
            "type": "select",
            "currentValue": current,
            "options": [
                {"name": "Low", "value": "low"},
                {"name": "High", "value": "high"},
                {"name": "Max", "value": "max"},
            ],
        }
    # The effort/thought-level selector agents expose as a session config
    # option (Zed's thought_level category; Claude and Gemini advertise their
    # thinking levels this way).
    return {
        "id": EFFORT_CONFIG_ID,
        "name": "Thinking level",
        "category": "thought_level",
        "type": "select",
        "currentValue": current,
        "options": [
            {"name": "Minimal", "value": "minimal"},
            {"name": "Low", "value": "low"},
            {"name": "Medium", "value": "medium"},
            {"name": "High", "value": "high"},
        ],
    }


def full_options(model, effort):
    return [model, mode_config(), effort_config(effort)]


def drift_model_config(current):
    # Options of the model-drift scenario: an agent that keeps its selected
    # model outside the client's control (like Mistral Vibe).
    return {
        "id": "model",
        "name": "Model",
        "category": "model",
        "type": "select",
        "currentValue": current,
        "options": [
            {"name": "GLM 5.3", "value": "glm-5-3"},
            {"name": "Mistral Medium 3.5", "value": "mistral-medium-3.5"},
        ],
    }


def send(message):
    sys.stdout.write(json.dumps(message, separators=(",", ":")) + "\n")
    sys.stdout.flush()


def result(request_id, payload):
    send({"jsonrpc": "2.0", "id": request_id, "result": payload})


def error(request_id, message, code=-32000, data=None):
    body = {"code": code, "message": message}
    if data is not None:
        body["data"] = data
    send({"jsonrpc": "2.0", "id": request_id, "error": body})


def notify(method, params):
    send({"jsonrpc": "2.0", "method": method, "params": params})


def read_message():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            return json.loads(line)
        except json.JSONDecodeError:
            continue
    return None


def call_client(method, params):
    global NEXT_ID
    request_id = NEXT_ID
    NEXT_ID += 1
    send({"jsonrpc": "2.0", "id": request_id, "method": method, "params": params})
    while True:
        message = read_message()
        if message is None:
            return None
        if message.get("id") == request_id:
            return message
        handle(message)


def session_update(update):
    notify("session/update", {"sessionId": SESSION_ID, "update": update})


def request_no_wait(method, params):
    """Send a request without blocking for the reply, so the client can be put
    into the position of having two questions outstanding at once."""
    global NEXT_ID
    request_id = NEXT_ID
    NEXT_ID += 1
    send({"jsonrpc": "2.0", "id": request_id, "method": method, "params": params})
    return request_id


def ask_permission(tool_call_id):
    session_update(
        {
            "sessionUpdate": "tool_call",
            "toolCallId": tool_call_id,
            "name": "write_file",
            "title": "Write notes.txt",
            "kind": "edit",
            "status": "pending",
        }
    )
    return request_no_wait(
        "session/request_permission",
        {
            "sessionId": SESSION_ID,
            "toolCall": {"toolCallId": tool_call_id, "title": "Write notes.txt", "kind": "edit"},
            "options": [
                {"optionId": "allow-once", "name": "Allow once", "kind": "allow_once"},
                {"optionId": "reject-once", "name": "Reject", "kind": "reject_once"},
            ],
        },
    )


def outcome_summary(outcome):
    if not outcome:
        return "unanswered"
    if outcome.get("outcome") == "cancelled":
        return "cancelled"
    return outcome.get("optionId") or "unknown"


def handle_prompt(request_id, params):
    # Text blocks are joined by a line break, as a real agent reads them.
    # user_text is the last block, the message the user typed: an agent answers
    # that, not the editor context or the session notes sent before it.
    texts = [
        block.get("text") or ""
        for block in params.get("prompt") or []
        if isinstance(block, dict) and block.get("type") == "text"
    ]
    text = "\n".join(texts)
    user_text = texts[-1] if texts else ""

    if SCENARIO == "prompt-probe":
        # Reports every text block the prompt carried, so a test can see what
        # the agent was sent and what it was not.
        session_update(
            {
                "sessionUpdate": "agent_message_chunk",
                "content": {"type": "text", "text": "\n---\n".join(texts)},
            }
        )
        result(request_id, {"stopReason": "end_turn"})
        return

    if SCENARIO == "kateai-ext":
        # Kate's client methods called by their extension names, as the
        # capability advertises them.
        call_client(
            "_kateai/suggest",
            {"sessionId": SESSION_ID, "suggestion": "extract a helper", "path": "/tmp/a.cpp", "line": 3},
        )
        session_update(
            {
                "sessionUpdate": "agent_message_chunk",
                "content": {"type": "text", "text": "ext-ok"},
            }
        )
        result(request_id, {"stopReason": "end_turn"})
        return

    if SCENARIO in ("flaky", "flaky-persistent"):
        # A transient drop of the agent's stream to its model provider: the
        # turn fails mid-response and Rust agents report the hyper/reqwest
        # transport error verbatim. "flaky" recovers on the next attempt;
        # "flaky-persistent" never does, so the client exhausts its budget.
        global PROMPT_COUNT
        PROMPT_COUNT += 1
        if SCENARIO == "flaky" and PROMPT_COUNT > 1:
            kind = "nudged" if "transient network error" in text else "replayed"
            session_update(
                {
                    "sessionUpdate": "agent_message_chunk",
                    "content": {"type": "text", "text": "flaky-recovered:" + kind},
                }
            )
            result(request_id, {"stopReason": "end_turn"})
            return
        session_update(
            {
                "sessionUpdate": "agent_message_chunk",
                "content": {"type": "text", "text": "partial answer"},
            }
        )
        error(
            request_id,
            "peer closed connection without sending complete message body (incomplete chunked read)",
            -32603,
        )
        return

    if SCENARIO in ("output-limit", "output-limit-persistent"):
        # Mistral Vibe's failure mode for a large file: the model announces the
        # write, then the completion is cut off at the output token limit, so
        # the turn ends with stopReason "max_tokens" and no tool call ran.
        # "output-limit" recovers once the client nudges it to split the write;
        # "output-limit-persistent" never does, so the client exhausts its budget.
        PROMPT_COUNT += 1
        if SCENARIO == "output-limit" and PROMPT_COUNT > 1:
            kind = "nudged" if "output token limit" in text else "replayed"
            session_update(
                {
                    "sessionUpdate": "agent_message_chunk",
                    "content": {"type": "text", "text": "output-limit-recovered:" + kind},
                }
            )
            result(request_id, {"stopReason": "end_turn"})
            return
        session_update(
            {
                "sessionUpdate": "agent_message_chunk",
                "content": {"type": "text", "text": "Now I will write the file"},
            }
        )
        result(request_id, {"stopReason": "max_tokens"})
        return

    if SCENARIO == "effort-drift":
        # The agent drops its thinking level mid-turn (an adaptive agent
        # deciding on its own). A client that forces a configured level must
        # push it back; the turn is held open until that push arrives.
        session_update(
            {
                "sessionUpdate": "config_option_update",
                "configOptions": full_options(model_config(CURRENT_MODEL), "low"),
            }
        )
        while True:
            message = read_message()
            if message is None:
                return
            if (
                message.get("method") == "session/set_config_option"
                and (message.get("params") or {}).get("configId") == EFFORT_CONFIG_ID
            ):
                handle(message)
                session_update(
                    {
                        "sessionUpdate": "agent_message_chunk",
                        "content": {"type": "text", "text": "effort:" + CURRENT_EFFORT},
                    }
                )
                result(request_id, {"stopReason": "end_turn"})
                return
            handle(message)

    if SCENARIO == "model-drift":
        # The agent switched its model behind the client's back mid-turn and
        # reports it; a client that pins the configured model must push it
        # back instead of following the switch.
        session_update(
            {
                "sessionUpdate": "config_option_update",
                "configOptions": [drift_model_config("glm-5-3"), mode_config()],
            }
        )
        session_update(
            {
                "sessionUpdate": "agent_message_chunk",
                "content": {"type": "text", "text": "drifted"},
            }
        )
        result(request_id, {"stopReason": "end_turn"})
        return

    if SCENARIO == "stringid":
        # JSON-RPC lets a reply quote the request id as a string. session/prompt
        # has no timeout, so a client that cannot match the id never finishes the
        # turn at all.
        session_update(
            {
                "sessionUpdate": "agent_message_chunk",
                "content": {"type": "text", "text": "string-id-ok"},
            }
        )
        result(str(request_id), {"stopReason": "end_turn"})
        return

    if SCENARIO == "toolstream":
        # A tool that reports its execution in pieces. Real agents send
        # tool_call_update with status "in_progress" and a growing content array
        # long before the terminal update: those in-progress updates are what the
        # card should stream, instead of showing nothing until the tool ends.
        session_update(
            {
                "sessionUpdate": "tool_call",
                "toolCallId": "call_stream",
                "name": "bash",
                "title": "Run build",
                "kind": "execute",
                "status": "pending",
            }
        )
        session_update(
            {
                "sessionUpdate": "tool_call_update",
                "toolCallId": "call_stream",
                "status": "in_progress",
                "content": [
                    {"type": "content", "content": {"type": "text", "text": "scanning dependencies"}}
                ],
            }
        )
        session_update(
            {
                "sessionUpdate": "tool_call_update",
                "toolCallId": "call_stream",
                "status": "in_progress",
                "content": [
                    {"type": "content", "content": {"type": "text", "text": "scanning dependencies"}},
                    {"type": "content", "content": {"type": "text", "text": "building target"}},
                ],
            }
        )
        session_update(
            {
                "sessionUpdate": "tool_call_update",
                "toolCallId": "call_stream",
                "status": "completed",
                "content": [
                    {"type": "content", "content": {"type": "text", "text": "scanning dependencies"}},
                    {"type": "content", "content": {"type": "text", "text": "building target"}},
                    {"type": "content", "content": {"type": "text", "text": "build finished"}},
                ],
            }
        )
        session_update(
            {
                "sessionUpdate": "agent_message_chunk",
                "content": {"type": "text", "text": "streamed"},
            }
        )
        result(request_id, {"stopReason": "end_turn"})
        return

    if SCENARIO == "permission":
        session_update(
            {
                "sessionUpdate": "tool_call",
                "toolCallId": "call_perm",
                "name": "write_file",
                "title": "Write notes.txt",
                "kind": "edit",
                "status": "pending",
            }
        )
        response = call_client(
            "session/request_permission",
            {
                "sessionId": SESSION_ID,
                "toolCall": {"toolCallId": "call_perm", "title": "Write notes.txt", "kind": "edit"},
                "options": [
                    {"optionId": "allow-once", "name": "Allow once", "kind": "allow_once"},
                    {"optionId": "reject-once", "name": "Reject", "kind": "reject_once"},
                ],
            },
        )
        option = (((response or {}).get("result") or {}).get("outcome") or {}).get("optionId")
        session_update(
            {
                "sessionUpdate": "agent_message_chunk",
                "content": {"type": "text", "text": f"permission:{option}"},
            }
        )
        result(request_id, {"stopReason": "end_turn"})
        return

    if SCENARIO == "permission-question":
        # An agent without ask_user tunnels its question through permission:
        # the options are answer labels, not allow/reject decisions.
        response = call_client(
            "session/request_permission",
            {
                "sessionId": SESSION_ID,
                "toolCall": {
                    "toolCallId": "call_question",
                    "title": "Ask a question",
                    "kind": "other",
                    "rawInput": {"question": "Which strategy should I use?"},
                },
                "options": [
                    {"optionId": "opt-conservative", "name": "conservative"},
                    {"optionId": "opt-balanced", "name": "balanced"},
                ],
            },
        )
        option = (((response or {}).get("result") or {}).get("outcome") or {}).get("optionId")
