TurnStatus::TurnStatus(QWidget *parent)
    : QWidget(parent)
{
    setObjectName(u"turnStatus"_s);
    setCursor(Qt::PointingHandCursor);
    setToolTip(i18n("Scroll to the newest message"));
    installEventFilter(this);

    auto *layout = new QHBoxLayout(this);
    layout->setContentsMargins(2, 2, 2, 2);
    layout->setSpacing(7);

    m_spinner = new QLabel(this);
    m_spinner->setFixedWidth(10);
    layout->addWidget(m_spinner);

    m_activity = new QLabel(this);
    layout->addWidget(m_activity);

    m_stats = new QLabel(this);
    layout->addWidget(m_stats);

    // Idle hint shares the left edge with the running line, so the strip does
    // not appear to jump when a turn starts.
    m_idle = new QLabel(this);
    layout->addWidget(m_idle);

    layout->addStretch();
    // Children eat mouse events by default, so clicks on the text never reach
    // the widget's eventFilter. Forward them for scroll-to-latest.
    for (QLabel *label : {m_spinner, m_activity, m_stats, m_idle}) {
        label->setAttribute(Qt::WA_TransparentForMouseEvents, true);
    }

    m_ticker = new QTimer(this);
    m_ticker->setInterval(120);
    connect(m_ticker, &QTimer::timeout, this, [this] {
        m_spinner->setText(spinnerFrame(m_elapsed.elapsed() / 120));
        refresh();
    });
    m_spinner->setText(spinnerFrame(0));

    applyStyle();
}

void TurnStatus::applyStyle()
{
    // The status strip sits on the composer strip, which is window chrome, so
    // its text uses the window-chrome colours. The spinner and the error
    // message keep their status colours.
    m_spinner->setStyleSheet(QStringLiteral("QLabel { color: %1; font-size: 12px; }").arg(ChatTheme::accent()));
    m_activity->setStyleSheet(QStringLiteral("QLabel { color: %1; font-size: 11px; }").arg(ChatTheme::windowText()));
    m_stats->setStyleSheet(QStringLiteral("QLabel { color: %1; font-size: 11px; }").arg(ChatTheme::windowTextMuted()));
    // refresh() re-derives the idle label's style from the current state and
    // restores the busy/idle visibility of the running widgets.
    refresh();
}

bool TurnStatus::eventFilter(QObject *watched, QEvent *event)
{
    if (event->type() == QEvent::MouseButtonRelease && watched == this) {
        Q_EMIT scrollToLatestRequested();
        return true;
    }
    return QWidget::eventFilter(watched, event);
}

void TurnStatus::setIdleText(const QString &text)
{
    m_idle->setText(text);
