    QList<int> visibleWindow() const;

    QList<Row> m_rows;
    bool m_expanded = false;
    QLabel *m_header = nullptr;
    QLabel *m_progress = nullptr;
    QPushButton *m_toggle = nullptr;
    QVBoxLayout *m_rowsLayout = nullptr;
