        const QString doneSheet = rowForDescription(widget, u"Done step"_s)
                                      ->findChild<QLabel *>(u"todoText"_s)
                                      ->styleSheet();
        QVERIFY2(doneSheet.contains(u"line-through"_s), qPrintable(doneSheet));
