        const QString pendingGlyphSheet = rowForDescription(widget, u"Pending step"_s)
                                              ->findChild<QLabel *>(u"todoGlyph"_s)
                                              ->styleSheet();
        QCOMPARE(pendingGlyphSheet, ChatTheme::todoGlyphPending());
    }

    void emptyPlanHidesTheWidget()
