/*
 * SPDX-FileCopyrightText: 2026 ObiWindu <Obi.wandu@proton.me>
 * SPDX-License-Identifier: LGPL-2.1-or-later
 *
 * Guards the two properties the chat panel's intent dock depends on:
 *
 *  1. A delegated agent task is drawn as a bordered box with its own
 *     background, so it reads as a distinct object rather than as more prose.
 *  2. It is compact -- the dock sits above the input and shares that strip
 *     with approval prompts, so the card has to stay small.
 */

#include "chattheme.h"
#include "subtaskwidget.h"

#include <QApplication>
#include <QColor>
#include <QLabel>
#include <QPushButton>
#include <QTest>
#include <QTextBrowser>

using namespace Qt::Literals::StringLiterals;
using namespace KateAi;

class TestIntentDock : public QObject
{
    Q_OBJECT

private Q_SLOTS:
    void testAgentTaskCardIsABorderedBoxWithBackground()
    {
        SubtaskWidget widget(u"task-1"_s);

        const QString style = widget.styleSheet();
        // A box: a border on the card, not just an accent rail.
        QVERIFY2(style.contains(u"QWidget#subtaskWidget"_s), qPrintable(style));
        QVERIFY2(style.contains(u"border:"_s), qPrintable(style));
        QVERIFY2(style.contains(u"border-radius:"_s), qPrintable(style));
        // And a background of its own, distinct from the panel backdrop.
        QVERIFY2(style.contains(u"background-color:"_s), qPrintable(style));
        QVERIFY2(!style.contains(ChatTheme::panelBg()), qPrintable(style));
    }

    void testAgentTaskCardStaysCompact()
    {
        SubtaskWidget widget(u"task-2"_s);

        const QString style = widget.styleSheet();
        // 10px padding was the old transcript-sized card; the docked variant
        // keeps well under that.
        QVERIFY2(!style.contains(u"10px"_s), qPrintable(style));

        // The header row is the part always on screen, so that is what has to
        // stay small: 11px title, 10px status.
        QVERIFY2(findLabelStyle(widget, QStringLiteral("font-size: 11px; font-weight: 600")),
                 qPrintable(style));
        QVERIFY2(findLabelStyle(widget, QStringLiteral("font-size: 10px;")), qPrintable(style));

        // The Cancel button is the reason the card lives in the dock; it has
        // to stay short enough not to dominate the strip.
        auto *cancel = widget.findChild<QPushButton *>();
        QVERIFY(cancel);
        QVERIFY2(cancel->maximumHeight() <= 22, qPrintable(QString::number(cancel->maximumHeight())));
    }

    void testAgentTaskCardActuallyPaintsItsBackground()
    {
        SubtaskWidget widget(u"paint-1"_s);

        // A plain QWidget subclass silently ignores a stylesheet
        // background-color unless WA_StyledBackground is set. Without this the
        // card renders fully transparent and the box never appears on screen,
        // even though the stylesheet is correct.
        QVERIFY2(widget.testAttribute(Qt::WA_StyledBackground),
                 "sub-agent card needs WA_StyledBackground to paint its box");
    }

    void testAgentTaskCardIsYellow()
    {
        // A delegated sub-agent is someone else's work, so its card is warm and
        // unmistakable next to the agent's own blue / green / violet tool cards.
        const QString style = ChatTheme::agentTaskCard();
        const int at = style.indexOf(u"background-color:"_s);
        QVERIFY2(at >= 0, qPrintable(style));
        const int valueStart = at + qstrlen("background-color:");
        const QString value = style.mid(valueStart, style.indexOf(u";"_s, valueStart) - valueStart).trimmed();
        const QColor colour(value);
        QVERIFY2(colour.isValid(), qPrintable(value));
        const int hue = colour.hue();
        QVERIFY2(hue >= 30 && hue <= 70,
                 qPrintable(QStringLiteral("card colour %1 has hue %2, which is not yellow")
                                .arg(colour.name(), QString::number(hue))));
        QVERIFY2(colour.saturation() > 40,
                 qPrintable(QStringLiteral("card colour %1 is too grey to read as yellow").arg(colour.name())));
    }

    void testThinkingPillPulseKeepsBothPhases()
    {
        // The pulse dims the pill between beats through the stylesheet rather
        // than through a QGraphicsOpacityEffect, which breaks colour-emoji
        // glyphs. Both phases have to exist, differ, and stay bare: the pill
        // is text colour alone, with no background or border to carry the
        // state, and at half its old footprint.
        const QString bright = ChatTheme::thinkingPill();
        const QString dim = ChatTheme::thinkingPillDim();
        QVERIFY2(bright != dim, "the pill needs a dim phase to pulse with");
        for (const QString &sheet : {bright, dim}) {
            QVERIFY2(!sheet.contains(u"background-color"_s), qPrintable(sheet));
            QVERIFY2(!sheet.contains(u"border: 1px"_s), qPrintable(sheet));
            QVERIFY2(sheet.contains(u"font-size: 7.2px"_s), qPrintable(sheet));
        }
        const QString work = ChatTheme::workingPill();
        const QString workDim = ChatTheme::workingPillDim();
        QVERIFY2(work != workDim, "the working pill needs a dim phase too");
        QVERIFY2(work.contains(u"font-size: 7.2px"_s), qPrintable(work));
    }

    void testRunningCardShowsTheDelegatedTask()
    {
        SubtaskWidget card(QStringLiteral("task-10"));
        card.startAgent(QStringLiteral("Reviewer"), QStringLiteral("code"),
                        QStringLiteral("Check the diff for the new parser"));

        // The delegated task is what the card is about, so it has to stay on
        // screen while the agent works. startAgent() used to clear it, which
        // left a running card with nothing in it but a timer.
        bool shown = false;
        for (const QTextBrowser *browser : card.findChildren<QTextBrowser *>()) {
            if (browser->isVisibleTo(&card) && browser->toPlainText().contains(u"Check the diff for the new parser")) {
                shown = true;
            }
        }
        QVERIFY2(shown, "a running sub-agent card must still name the work it was given");
    }

    void testRunningCardShowsWhatTheSubAgentIsDoing()
    {
        SubtaskWidget card(QStringLiteral("task-11"));
        card.startAgent(QStringLiteral("Reviewer"), QStringLiteral("code"), QStringLiteral("Check the diff"));

        // Before the sub-agent reports anything there is no step to show.
        QVERIFY2(!hasVisibleLabelContaining(card, u"read_file"_s),
                 "no live step should be on the card before the first one arrives");

        card.appendActivity(QStringLiteral("→ read_file src/parser.cpp"), false);
        QVERIFY2(hasVisibleLabelContaining(card, u"src/parser.cpp"_s),
                 "the step the sub-agent is on has to be visible on the card itself, "
                 "not only in the collapsed activity log");

        // The answer takes over when the run ends.
        card.finishAgent(ToolResult{});
        QVERIFY2(!hasVisibleLabelContaining(card, u"src/parser.cpp"_s),
                 "the finished card must not keep reporting a step from a run that is over");
    }

    void testRunningAgentTaskKeepsStateColourInTheBorder()
    {
        SubtaskWidget running(QStringLiteral("task-3"));
        running.startAgent(QStringLiteral("Reviewer"), QStringLiteral("code"), QStringLiteral("Check the diff"));

        const QString style = running.styleSheet();
        // Outcome is carried by the border colour, so a running task is
        // visually distinct without needing a separate legend.
        QVERIFY2(style.contains(ChatTheme::accent()), qPrintable(style));

        SubtaskWidget finished(QStringLiteral("task-4"));
        finished.startAgent(QStringLiteral("Reviewer"), QStringLiteral("code"), QStringLiteral("Check the diff"));
        finished.finishAgent(ToolResult{});
        QVERIFY2(finished.styleSheet().contains(ChatTheme::success()),
                 qPrintable(finished.styleSheet()));
    }

    void testDockChromeStaysFlat()
    {
        // The dock itself must not draw a box, and must not restyle its
        // children -- a descendant rule would flatten the borders on the very
        // cards the dock exists to frame. It does fill with the window chrome
        // colour: the dock is part of the window, pinned to the composer strip
        // (and under a built-in preset that colour is the panel colour, so the
        // dock still paints nothing of its own).
        const QString dock = ChatTheme::intentDock();
        QVERIFY(dock.contains(u"QWidget#intentDock"_s));
        QVERIFY2(dock.contains(ChatTheme::windowBg()), qPrintable(dock));
        QVERIFY2(!dock.contains(u"QWidget#intentDock QWidget"_s), qPrintable(dock));
        QVERIFY2(!dock.contains(u"border-radius"_s), qPrintable(dock));
    }

    void testApprovalRowIsABox()
    {
        const QString row = ChatTheme::intentApprovalRow();
        QVERIFY2(row.contains(u"QWidget#approvalRow"_s), qPrintable(row));
        QVERIFY2(row.contains(u"background-color:"_s), qPrintable(row));
        QVERIFY2(row.contains(u"border:"_s), qPrintable(row));
    }

private:
    static bool findLabelStyle(const QWidget &root, const QString &needle)
    {
        const auto labels = root.findChildren<QLabel *>();
        for (const QLabel *label : labels) {
            if (label->styleSheet().contains(needle)) {
                return true;
            }
        }
        return false;
    }

    static bool hasVisibleLabelContaining(QWidget &root, const QString &needle)
    {
        const auto labels = root.findChildren<QLabel *>();
        for (const QLabel *label : labels) {
            if (label->isVisibleTo(&root) && label->text().contains(needle)) {
                return true;
            }
        }
        return false;
    }
};

QTEST_MAIN(TestIntentDock)
#include "test_intentdock.moc"

#include "sandbox.h"

#include <QCoreApplication>
#include <QDir>
#include <QFile>
#include <QTemporaryDir>
#include <QTest>

using namespace Qt::Literals::StringLiterals;
using namespace KateAi;

class TestSandbox : public QObject
{
    Q_OBJECT

private Q_SLOTS:
    void pathEscapeIsBlocked()
    {
        QTemporaryDir dir;
        QVERIFY(dir.isValid());
        Sandbox box(dir.path(), SandboxProfile::Workspace);
        QString error;
        QVERIFY(box.allowsWrite(u"src/main.cpp"_s, &error));
        QVERIFY(!box.allowsWrite(u"../outside.txt"_s, &error));
        QVERIFY(error.contains(u"outside"_s));
    }

    void writeOutsideWorkspaceIsBlockedEvenWhenTheDirectoryIsMissing()
    {
        // The containment check used to run only on the canonical path, which
        // does not exist when neither the file nor its parent directory does.
        // A write to <new-dir>/x.txt therefore succeeded in every profile,
        // including Strict. The escape target is a sibling of the workspace
        // under the system temp dir, so it is outside on every platform
        // (Windows included: no Unix-only "/tmp" literal).
        QTemporaryDir dir;
        QVERIFY(dir.isValid());
        const QString target = QDir::tempPath() + u"/kateai-sandbox-escape-%1-%2/outside.txt"_s
                                   .arg(QCoreApplication::applicationPid())
                                   .arg(reinterpret_cast<quintptr>(&dir));
        for (SandboxProfile profile : {SandboxProfile::Workspace, SandboxProfile::Strict}) {
            Sandbox box(dir.path(), profile);
            QString error;
            QVERIFY2(!box.allowsWrite(target, &error), "the write was allowed");
            QVERIFY(error.contains(u"outside"_s));
        }
        // The same path inside the workspace is fine.
        Sandbox box(dir.path(), SandboxProfile::Workspace);
        QString error;
        QVERIFY(box.allowsWrite(u"sub/dir/file.txt"_s, &error));
    }

    void readsOutsideTheWorkspaceAreBlocked()
    {
        // The read tools are approved without a prompt, so a profile that
        // does not confine them lets the agent read any file of the host.
        // The "outside" file lives in a second temp dir: portable on every
        // platform (no Unix-only "/etc/passwd" literal, which maps to a
        // drive-relative path on Windows).
        QTemporaryDir dir;
        QVERIFY(dir.isValid());
        QTemporaryDir outside;
        QVERIFY(outside.isValid());
        const QString outsideFile = outside.filePath(u"secret.txt"_s);
        Sandbox box(dir.path(), SandboxProfile::Workspace);
        QString error;
        QVERIFY(!box.allowsRead(outsideFile, &error));
        // Inside the workspace it still works.
        QFile file(dir.filePath(u"inside.txt"_s));
        QVERIFY(file.open(QIODevice::WriteOnly));
        file.write("x");
        file.close();
        QVERIFY(box.allowsRead(u"inside.txt"_s, &error));
        // The opt-in lifts the confinement again.
        Sandbox open(dir.path(), SandboxProfile::Workspace, {}, true);
        QVERIFY(open.allowsRead(outsideFile, &error));
    }

    void readOnlyCommandRejectsSubstitution()
    {
        // "cat $(...)" has a read-only executable and still runs whatever the
        // substitution expands to. Such a command was auto-approved.
        Sandbox box(QStringLiteral("/tmp"), SandboxProfile::Workspace);
        QVERIFY(!box.isReadOnlyCommand(u"cat \"$(python3 -c 'import os')\""_s));
        QVERIFY(!box.isReadOnlyCommand(u"cat `id`"_s));
        QVERIFY(!box.isReadOnlyCommand(u"ls &"_s));
        // The ordinary read-only commands are unaffected.
        QVERIFY(box.isReadOnlyCommand(u"ls -la"_s));
        QVERIFY(box.isReadOnlyCommand(u"cat file.txt"_s));
    }

    void envWrapperIsNotReadOnly()
    {
        // "env" with no command only prints the environment, but
        // "env bash -c …" executes an arbitrary program: a read-only
        // allowlist entry would auto-approve code execution in Ask mode.
        Sandbox box(QDir::tempPath(), SandboxProfile::Workspace);
        QVERIFY(!box.isReadOnlyCommand(u"env bash -c 'echo hi'"_s));
        QVERIFY(!box.isReadOnlyCommand(u"env python3 -c 'print(1)'"_s));
        QVERIFY(!box.isReadOnlyCommand(u"env FOO=1 ls -la"_s));
        // "printenv" only ever prints.
        QVERIFY(box.isReadOnlyCommand(u"printenv"_s));
        QVERIFY(box.isReadOnlyCommand(u"printenv HOME"_s));
    }

    void processSubstitutionIsNotReadOnly()
    {
        // "<(…)" runs a program inline, exactly like "$(…)": the executable
        // in front of it is read-only but the substitution is not.
        Sandbox box(QDir::tempPath(), SandboxProfile::Workspace);
        QVERIFY(!box.isReadOnlyCommand(u"diff <(python3 -c 'print(1)') b.txt"_s));
        QVERIFY(!box.isReadOnlyCommand(u"sort <(curl http://example.invalid) | head"_s));
        QVERIFY(!box.isReadOnlyCommand(u"cat >(gzip > out.gz)"_s));
        // A plain pipe of read-only commands stays read-only.
        QVERIFY(box.isReadOnlyCommand(u"cat a.txt | sort | head"_s));
    }

    void deniedDirectoryMatchesItself()
    {
        // "**/.ssh/**" did not match the directory itself, so a command that
        // named the directory was not caught.
        QVERIFY(Sandbox::globMatch(u"**/.ssh/**"_s, u"/home/user/.ssh"_s));
        QVERIFY(Sandbox::globMatch(u"**/.ssh/**"_s, u"/home/user/.ssh/id_rsa"_s));
    }

    void envFileIsDenied()
    {
        QTemporaryDir dir;
        QVERIFY(dir.isValid());
        QFile env(dir.filePath(u".env"_s));
        QVERIFY(env.open(QIODevice::WriteOnly));
        env.write("SECRET=1\n");
        env.close();

        Sandbox box(dir.path(), SandboxProfile::Off);
        QString error;
        QVERIFY(!box.allowsRead(u".env"_s, &error));
        QVERIFY(box.isDenied(dir.filePath(u".env"_s)));
        QVERIFY(Sandbox::globMatch(u"**/.env"_s, dir.filePath(u".env"_s)));
        QVERIFY(Sandbox::globMatch(u"**/*.pem"_s, u"/tmp/cert.pem"_s));
    }

    void readOnlyBlocksWrites()
    {
        QTemporaryDir dir;
        QVERIFY(dir.isValid());
        Sandbox box(dir.path(), SandboxProfile::ReadOnly);
        QString error;
        QVERIFY(box.allowsRead(u"README.md"_s, &error));
        QVERIFY(!box.allowsWrite(u"README.md"_s, &error));
    }

    void strictBlocksOutsideReads()
    {
        QTemporaryDir dir;
        QVERIFY(dir.isValid());
        QTemporaryDir outside;
        QVERIFY(outside.isValid());
        Sandbox box(dir.path(), SandboxProfile::Strict);
        QString error;
        QVERIFY(!box.allowsRead(outside.filePath(u"secret.txt"_s), &error));
        QVERIFY(box.allowsRead(u"src/foo.cpp"_s, &error) || error.isEmpty() || !error.contains(u"deny"_s));
        const QString resolved = QDir::fromNativeSeparators(box.resolve(u"src/foo.cpp"_s, &error, true));
        const QString root = QDir::fromNativeSeparators(QDir(dir.path()).canonicalPath().isEmpty()
                                                            ? QDir(dir.path()).absolutePath()
                                                            : QDir(dir.path()).canonicalPath());
#if defined(Q_OS_WIN)
        // Windows filesystems are case-insensitive; the temp dir may be
        // addressed through an 8.3 short name vs. the long canonical form.
        QVERIFY(resolved.startsWith(root, Qt::CaseInsensitive));
#else
        QVERIFY(resolved.startsWith(root));
#endif
    }

    void dangerousCommands()
    {
        Sandbox box(QDir::tempPath(), SandboxProfile::Workspace);
        QVERIFY(box.isAlwaysDeniedCommand(u"rm -rf /"_s));
        QVERIFY(box.isDangerousCommand(u"sudo make install"_s));
        QVERIFY(box.isReadOnlyCommand(u"ls -la"_s));
        QVERIFY(box.isReadOnlyCommand(u"git status"_s));
        QVERIFY(!box.isReadOnlyCommand(u"ls && rm -rf src"_s));
    }

    void alwaysDeniedCoversRootHomeAndStarRemoval()
    {
        Sandbox box(QDir::tempPath(), SandboxProfile::Workspace);
        QVERIFY(box.isAlwaysDeniedCommand(u"rm -rf /"_s));
        QVERIFY(box.isAlwaysDeniedCommand(u"rm -rf /*"_s));
        QVERIFY(box.isAlwaysDeniedCommand(u"rm -rf ~"_s));
        QVERIFY(box.isAlwaysDeniedCommand(u"rm -rf ~/Documents"_s));
        QVERIFY(box.isAlwaysDeniedCommand(u"rm -r /"_s));
        // The flags and --no-preserve-root may appear in any order.
        QVERIFY(box.isAlwaysDeniedCommand(u"rm -rf --no-preserve-root /"_s));
        QVERIFY(box.isAlwaysDeniedCommand(u"rm --no-preserve-root -rf /"_s));
        QVERIFY(box.isAlwaysDeniedCommand(u"sudo rm -rf ~"_s));
        // Deeper paths are a normal cleanup the permission prompt can judge.
        QVERIFY(!box.isAlwaysDeniedCommand(u"rm -rf /etc"_s));
        QVERIFY(!box.isAlwaysDeniedCommand(u"rm -rf /tmp/build"_s));
        QVERIFY(!box.isAlwaysDeniedCommand(u"rm -rf src"_s));
        QVERIFY(!box.isAlwaysDeniedCommand(u"rm -rf ./build"_s));
    }

    void emptyWorkspaceRootStaysEmpty()
    {
        // QDir("").absolutePath() is the process working directory: rooting
        // the sandbox there would silently confine to a directory the caller
        // never chose, and every guard that checks for an empty root would
        // stop firing.
        Sandbox box(QString(), SandboxProfile::Workspace);
        QVERIFY(box.workspaceRoot().isEmpty());
    }

    void globWorkspaceMatch()
    {
        QVERIFY(Sandbox::globMatch(u"**/*.cpp"_s, u"src/plugin.cpp"_s));
        QVERIFY(Sandbox::globMatch(u"*.json"_s, u"kateai.json"_s));
        QVERIFY(Sandbox::globMatch(u"**/.ssh/**"_s, u"/home/me/.ssh/id_rsa"_s));
    }

    void globCharacterClasses()
    {
        // A deny glob with a character class used to have its brackets
        // escaped as literals and silently match nothing.
        QVERIFY(Sandbox::globMatch(u"**/*.key[0-9]"_s, u"/home/me/backup.key5"_s));
        QVERIFY(Sandbox::globMatch(u"**/*.key[0-9]"_s, u"backup.key5"_s));
        QVERIFY(!Sandbox::globMatch(u"**/*.key[0-9]"_s, u"/home/me/backup.keyx"_s));
        // Negation, ranges, and an unmatched bracket. A negated class still
        // requires a character, so "confi" alone cannot match "confi[!g]".
        QVERIFY(Sandbox::globMatch(u"**/confi[!g]"_s, u"/home/me/confiv"_s));
        QVERIFY(!Sandbox::globMatch(u"**/confi[!g]"_s, u"/home/me/config"_s));
        QVERIFY(!Sandbox::globMatch(u"**/confi[!g]"_s, u"/home/me/confi"_s));
        QVERIFY(Sandbox::globMatch(u"**/key[a-c]x"_s, u"/home/me/keybx"_s));
        // A ']' right after '[' is a literal member.
        QVERIFY(Sandbox::globMatch(u"**/x[]y]z"_s, u"/home/me/x]z"_s));
        // No closing bracket: a literal '['.
        QVERIFY(Sandbox::globMatch(u"**/a[b"_s, u"/home/me/a[b"_s));
    }

    void symlinkEscapeIsBlocked()
    {
        QTemporaryDir dir;
        QVERIFY(dir.isValid());
        QTemporaryDir outside;
        QVERIFY(outside.isValid());

        // A directory link that points out of the workspace. The classic
        // escape: the path as written stays inside, the target does not.
        QVERIFY(QDir().mkpath(dir.path() + u"/inside"_s));
        if (!QFile::link(outside.path(), dir.path() + u"/inside/escape"_s)) {
            QSKIP("Symlinks unavailable on this filesystem");
        }
        QFile outsideFile(outside.filePath(u"secret.txt"_s));
        QVERIFY(outsideFile.open(QIODevice::WriteOnly));
        outsideFile.write("secret\n");
        outsideFile.close();

        Sandbox box(dir.path(), SandboxProfile::Workspace);
        QString error;
        // Writing through the link is refused, and says where it resolved to.
        QVERIFY(!box.allowsWrite(u"inside/escape/secret.txt"_s, &error));
        QVERIFY(error.contains(u"outside the workspace"_s));
        QVERIFY(box.resolve(u"inside/escape/secret.txt"_s, &error, true).isEmpty());
        error.clear();
        // So is a brand new file that would land outside via the link.
        QVERIFY(box.resolve(u"inside/escape/new.txt"_s, &error, true).isEmpty());
        QVERIFY(error.contains(u"outside the workspace"_s));
        // The real file inside the workspace is untouched by all of this.
        QVERIFY(box.allowsWrite(u"inside/keep.txt"_s, &error));
    }

    void symlinkEscapeBlockedForReadInStrict()
    {
        QTemporaryDir dir;
        QVERIFY(dir.isValid());
        QTemporaryDir outside;
