class TestCheckpoints : public QObject
{
    Q_OBJECT

private:
    static void writeFile(const QString &path, const QString &contents)
    {
        QDir().mkpath(QFileInfo(path).absolutePath());
        QFile file(path);
        QVERIFY(file.open(QIODevice::WriteOnly | QIODevice::Truncate | QIODevice::Text));
        file.write(contents.toUtf8());
    }

    static QString readFile(const QString &path)
    {
        QFile file(path);
        if (!file.open(QIODevice::ReadOnly | QIODevice::Text)) {
            return {};
        }
        return QString::fromUtf8(file.readAll());
    }

private Q_SLOTS:
    void initTestCase()
    {
        // Checkpoints need git; skip rather than fail when it is missing.
        QProcess probe;
        probe.start(u"git"_s, QStringList{u"--version"_s});
        m_hasGit = probe.waitForFinished(5000) && probe.exitCode() == 0;
    }

    void init()
    {
        m_workspace = std::make_unique<QTemporaryDir>();
        QVERIFY(m_workspace->isValid());
    }

    void cleanup()
    {
        m_workspace.reset();
    }

    void disabledManagerDoesNothing()
    {
        CheckpointManager manager;
        manager.setWorkspace(m_workspace->path());
        manager.setEnabled(false);
        QVERIFY(!manager.isAvailable());
        QString error;
        QVERIFY(manager.createCheckpoint(u"nope"_s, &error).isEmpty());
        QVERIFY(manager.checkpoints().isEmpty());
    }

    void createAndListSnapshots()
    {
        if (!m_hasGit) {
            QSKIP("git is not available");
        }
        writeFile(m_workspace->path() + u"/a.txt"_s, u"original"_s);

        CheckpointManager manager;
        manager.setWorkspace(m_workspace->path());
        manager.setRetention(10);
        QVERIFY(manager.isAvailable());

        QString error;
        const QString first = manager.createCheckpoint(u"first"_s, &error);
        QVERIFY2(!first.isEmpty(), qPrintable(error));
        QCOMPARE(manager.checkpoints().size(), 1);
        QCOMPARE(manager.checkpoints().first().label, u"first"_s);

        writeFile(m_workspace->path() + u"/a.txt"_s, u"changed"_s);
        const QString second = manager.createCheckpoint(u"second"_s, &error);
        QVERIFY2(!second.isEmpty(), qPrintable(error));
        QVERIFY(second != first);

        const QList<CheckpointInfo> checkpoints = manager.checkpoints();
        QCOMPARE(checkpoints.size(), 2);
        // Newest first.
        QCOMPARE(checkpoints.at(0).label, u"second"_s);
        QCOMPARE(checkpoints.at(1).label, u"first"_s);
        QCOMPARE(checkpoints.at(0).shortId.size(), 8);
    }

    void emptyCheckpointIsStillARestorePoint()
    {
        if (!m_hasGit) {
            QSKIP("git is not available");
        }
        writeFile(m_workspace->path() + u"/a.txt"_s, u"same"_s);

        CheckpointManager manager;
        manager.setWorkspace(m_workspace->path());
        QString error;
        const QString before = manager.createCheckpoint(u"before"_s, &error);
        QVERIFY2(!before.isEmpty(), qPrintable(error));
        // Nothing changed, but the user asked for a restore point.
        const QString again = manager.createCheckpoint(u"again"_s, &error);
        QVERIFY2(!again.isEmpty(), qPrintable(error));
        QCOMPARE(manager.checkpoints().size(), 2);
    }

    void restoreRevertsEditsAndRemovesAddedFiles()
    {
        if (!m_hasGit) {
            QSKIP("git is not available");
        }
        writeFile(m_workspace->path() + u"/a.txt"_s, u"original"_s);
        writeFile(m_workspace->path() + u"/nested/b.txt"_s, u"keep me"_s);

        CheckpointManager manager;
        manager.setWorkspace(m_workspace->path());
        QString error;
        const QString checkpoint = manager.createCheckpoint(u"baseline"_s, &error);
        QVERIFY2(!checkpoint.isEmpty(), qPrintable(error));

        // Mutate: modify an existing file, add a new one, delete another.
        writeFile(m_workspace->path() + u"/a.txt"_s, u"broken"_s);
        writeFile(m_workspace->path() + u"/added.txt"_s, u"should not survive"_s);
        QVERIFY(QFile::remove(m_workspace->path() + u"/nested/b.txt"_s));

        QCOMPARE(manager.changedFileCount(checkpoint), 3);

        QVERIFY2(manager.restoreCheckpoint(checkpoint, &error), qPrintable(error));
        QCOMPARE(readFile(m_workspace->path() + u"/a.txt"_s), u"original"_s);
        QCOMPARE(readFile(m_workspace->path() + u"/nested/b.txt"_s), u"keep me"_s);
        QVERIFY(!QFileInfo::exists(m_workspace->path() + u"/added.txt"_s));
        QCOMPARE(manager.changedFileCount(checkpoint), 0);
    }

    void restoreLeavesProtectedFilesUntouched()
    {
        if (!m_hasGit) {
            QSKIP("git is not available");
        }
        writeFile(m_workspace->path() + u"/a.txt"_s, u"original"_s);
        writeFile(m_workspace->path() + u"/.kateai/mcp.json"_s, u"safe config"_s);

        CheckpointManager manager;
        manager.setWorkspace(m_workspace->path());
        QString error;
        const QString checkpoint = manager.createCheckpoint(u"baseline"_s, &error);
        QVERIFY2(!checkpoint.isEmpty(), qPrintable(error));

        // After the snapshot the agent plants automation and breaks a file. The
        // snapshot captured the safe mcp.json, so a restore that writes it back
        // would reinstate snapshot content into a protected path.
        writeFile(m_workspace->path() + u"/.kateai/mcp.json"_s, u"planted config"_s);
        writeFile(m_workspace->path() + u"/a.txt"_s, u"broken"_s);

        QVERIFY2(manager.restoreCheckpoint(checkpoint, &error), qPrintable(error));
        // The snapshot's own content is restored...
        QCOMPARE(readFile(m_workspace->path() + u"/a.txt"_s), u"original"_s);
        // ...but a protected path is neither overwritten nor deleted: the
        // working copy survives the restore exactly as it was.
        QCOMPARE(readFile(m_workspace->path() + u"/.kateai/mcp.json"_s), u"planted config"_s);
    }

    // Every file RulesLoader feeds into the system prompt is automation the
    // agent must not be able to plant through a snapshot, not just KATEAI.md.
    void restoreLeavesRuleFilesUntouched()
    {
        if (!m_hasGit) {
            QSKIP("git is not available");
        }
        const QStringList ruleFiles = {
            u"/AGENTS.md"_s,
            u"/CLAUDE.md"_s,
            // .clinerules/.kilocoderules work as a root file *and* as a
            // directory of rule files; both forms must survive. A workspace
            // only has one form per name (git cannot track both), so each
            // name exercises one here.
            u"/.clinerules"_s,
            u"/.kilocoderules/team.md"_s,
            u"/.kateai/agents/reviewer.md"_s,
        };
        writeFile(m_workspace->path() + u"/a.txt"_s, u"original"_s);
        for (const QString &relative : ruleFiles) {
            writeFile(m_workspace->path() + relative, u"safe rules"_s);
        }

        CheckpointManager manager;
        manager.setWorkspace(m_workspace->path());
        QString error;
        const QString checkpoint = manager.createCheckpoint(u"baseline"_s, &error);
        QVERIFY2(!checkpoint.isEmpty(), qPrintable(error));

        for (const QString &relative : ruleFiles) {
            writeFile(m_workspace->path() + relative, u"planted rules"_s);
        }
        writeFile(m_workspace->path() + u"/a.txt"_s, u"broken"_s);

        QVERIFY2(manager.restoreCheckpoint(checkpoint, &error), qPrintable(error));
        QCOMPARE(readFile(m_workspace->path() + u"/a.txt"_s), u"original"_s);
        for (const QString &relative : ruleFiles) {
            QCOMPARE(readFile(m_workspace->path() + relative), u"planted rules"_s);
        }
    }

    void diffReportsChangesAgainstTheSnapshot()
    {
        if (!m_hasGit) {
            QSKIP("git is not available");
        }
        writeFile(m_workspace->path() + u"/a.txt"_s, u"line one\nline two\n"_s);

        CheckpointManager manager;
        manager.setWorkspace(m_workspace->path());
        QString error;
        const QString checkpoint = manager.createCheckpoint(u"baseline"_s, &error);
        QVERIFY2(!checkpoint.isEmpty(), qPrintable(error));
        QVERIFY(manager.diffAgainstCheckpoint(checkpoint).isEmpty());

        writeFile(m_workspace->path() + u"/a.txt"_s, u"line one\nline changed\n"_s);
        const QString diff = manager.diffAgainstCheckpoint(checkpoint);
        QVERIFY(diff.contains(u"-line two"_s));
        QVERIFY(diff.contains(u"+line changed"_s));

        // Long diffs are truncated rather than dumped into the transcript.
        QString huge;
        for (int i = 0; i < 5000; ++i) {
            huge += QStringLiteral("line %1\n").arg(i);
        }
        writeFile(m_workspace->path() + u"/big.txt"_s, huge);
        const QString truncated = manager.diffAgainstCheckpoint(checkpoint, 100);
        QVERIFY(truncated.contains(u"truncated"_s));
    }

    void retentionKeepsTheNewestSnapshots()
    {
        if (!m_hasGit) {
            QSKIP("git is not available");
        }
        CheckpointManager manager;
        manager.setWorkspace(m_workspace->path());
        manager.setRetention(3);

        QString error;
        for (int i = 0; i < 6; ++i) {
            writeFile(m_workspace->path() + u"/f.txt"_s, QStringLiteral("rev %1").arg(i));
            QVERIFY2(!manager.createCheckpoint(QStringLiteral("rev %1").arg(i), &error).isEmpty(), qPrintable(error));
        }

        const QList<CheckpointInfo> checkpoints = manager.checkpoints();
        QVERIFY(checkpoints.size() <= 4);
        QVERIFY(checkpoints.size() >= 2);
        // The newest snapshot is still reachable after pruning.
        QCOMPARE(checkpoints.first().label, u"rev 5"_s);
    }

    void restoringAnUnknownCheckpointFails()
    {
        if (!m_hasGit) {
            QSKIP("git is not available");
        }
        writeFile(m_workspace->path() + u"/a.txt"_s, u"x"_s);
        CheckpointManager manager;
        manager.setWorkspace(m_workspace->path());
        QString error;
        QVERIFY(manager.createCheckpoint(u"one"_s, &error).isEmpty() == false);
        QVERIFY(!manager.restoreCheckpoint(u"deadbeefdeadbeefdeadbeefdeadbeefdeadbeef"_s, &error));
        QVERIFY(!error.isEmpty());
        QVERIFY(!manager.restoreCheckpoint(QString(), &error));
        // The workspace must be untouched by the failed restore.
        QCOMPARE(readFile(m_workspace->path() + u"/a.txt"_s), u"x"_s);
    }

    void theProjectsOwnGitHistoryIsNeverTouched()
    {
        if (!m_hasGit) {
            QSKIP("git is not available");
        }
        QProcess init;
        init.setWorkingDirectory(m_workspace->path());
        init.start(u"git"_s, QStringList{u"init"_s, u"--quiet"_s});
        QVERIFY(init.waitForFinished(10000));

        writeFile(m_workspace->path() + u"/tracked.txt"_s, u"real content"_s);
        QProcess add;
        add.setWorkingDirectory(m_workspace->path());
        add.start(u"git"_s, QStringList{u"add"_s, u"-A"_s});
        QVERIFY(add.waitForFinished(10000));
        QProcess commit;
        commit.setWorkingDirectory(m_workspace->path());
        commit.start(u"git"_s, QStringList{u"-c"_s,
                                          u"user.name=t"_s,
                                          u"-c"_s,
                                          u"user.email=t@t"_s,
                                          u"commit"_s,
                                          u"--quiet"_s,
                                          u"-m"_s,
                                          u"real commit"_s});
        QVERIFY(commit.waitForFinished(10000));

        CheckpointManager manager;
        manager.setWorkspace(m_workspace->path());
        QString error;
        QVERIFY2(!manager.createCheckpoint(u"shadow"_s, &error).isEmpty(), qPrintable(error));

        // The snapshot repository lives outside the workspace, and the
        // project's own log still shows exactly the one real commit.
        QVERIFY(!QFileInfo::exists(m_workspace->path() + u"/.kateai/checkpoints"_s));
        QProcess log;
        log.setWorkingDirectory(m_workspace->path());
        log.start(u"git"_s, QStringList{u"log"_s, u"--oneline"_s});
        QVERIFY(log.waitForFinished(10000));
        const QString history = QString::fromUtf8(log.readAllStandardOutput());
        QCOMPARE(history.count(u"real commit"_s), 1);
    }

private:
    std::unique_ptr<QTemporaryDir> m_workspace;
    bool m_hasGit = false;
};

QTEST_GUILESS_MAIN(TestCheckpoints)
#include "test_checkpoints.moc"

#include "types.h"

#include <QJsonArray>
#include <QJsonDocument>
#include <QJsonObject>
#include <QTest>

using namespace Qt::Literals::StringLiterals;
using namespace KateAi;

class TestProviders : public QObject
{
    Q_OBJECT

private Q_SLOTS:
    void compressTextStaysInsideItsBudget()
    {
        // The indicator used to be added after the cut, so the result was
        // longer than the caller asked for.
        const QString text = QString(500, QLatin1Char('x'));
        const QString compressed = compressText(text, 100, true);
        QVERIFY2(compressed.size() <= 100,
                 qPrintable(QStringLiteral("compressText returned %1 characters").arg(compressed.size())));
        QVERIFY(compressed.contains(u"truncated"_s));
    }

    void truncateSafeDoesNotSplitASurrogatePair()
    {
        // A cut in the middle of an astral character leaves half of it behind,
        // and a lone surrogate is serialised as U+FFFD.
        // An emoji (a surrogate pair in UTF-16) followed by three letters.
        const QString text = QString::fromUtf8("\xF0\x9F\x98\x80" "abc");
        const QString cut = truncateSafe(text, 1);
        QVERIFY2(cut.isEmpty() || !cut.at(cut.size() - 1).isHighSurrogate(),
                 "the cut left a lone high surrogate behind");
        const QString full = truncateSafe(text, 100);
        QCOMPARE(full, text);
    }

    void smartCompressContextStaysInsideItsBudget()
    {
        // The marker used to be added on top of the kept head and tail.
        const QString text = QString(2000, QLatin1Char('x'));
        const QString compressed = smartCompressContext(text, 500, true);
        QVERIFY2(compressed.size() <= 500,
                 qPrintable(QStringLiteral("smartCompressContext returned %1 characters").arg(compressed.size())));
    }

    void smartCompressContextDoesNotSplitASurrogatePair()
    {
        const QString text = QString::fromUtf8("\xF0\x9F\x98\x80") + QString(2000, QLatin1Char('x'));
        const QString compressed = smartCompressContext(text, 500, true);
        for (int i = 0; i < compressed.size(); ++i) {
            const QChar c = compressed.at(i);
            if (c.isHighSurrogate()) {
                QVERIFY2(i + 1 < compressed.size() && compressed.at(i + 1).isLowSurrogate(),
                         "the compression left a lone high surrogate behind");
                ++i;
            } else {
                QVERIFY2(!c.isLowSurrogate(), "the compression left a lone low surrogate behind");
            }
        }
    }

    void aTelegramProviderHasAnId()
    {
        // The enumerator fell through to "grok", so the provider could not be
        // selected at all.
        QCOMPARE(providerId(Provider::Telegram), u"telegram"_s);
        QCOMPARE(providerFromId(u"telegram"_s), Provider::Telegram);
    }

    void anEmptyBaseUrlFallsBackToTheProviderDefault()
    {
        Settings settings;
        settings.provider = Provider::OpenAICompatible;
        settings.openaiCompatibleUrl.clear();
        QVERIFY(!providerBaseUrl(settings).isEmpty());
        settings.provider = Provider::ClaudeCompatible;
        settings.claudeCompatibleUrl.clear();
        QVERIFY(!providerBaseUrl(settings).isEmpty());
    }

    void noProviderShipsHardCodedModelNames()
    {
        // Model names used to be baked into defaultModels() and into the
        // Settings defaults, which went stale on every release and offered
        // models a given key could not reach. Everything must come from the
        // provider's own catalogue now.
        const QList<Provider> all = {Provider::Grok,
                                     Provider::OpenAI,
                                     Provider::OpenRouter,
                                     Provider::DeepSeek,
                                     Provider::OpenAICompatible,
                                     Provider::ClaudeCompatible,
                                     Provider::Kilo,
                                     Provider::Acp,
                                     Provider::OpenCode};
        for (const Provider provider : all) {
            QVERIFY2(defaultModels(provider).isEmpty(),
                     "defaultModels() must not hard-code model names");
        }

        Settings fresh;
        QVERIFY2(fresh.grokModel.isEmpty(), "Settings must not default to a model name");
        QVERIFY2(fresh.openaiModel.isEmpty(), "Settings must not default to a model name");
        QVERIFY2(fresh.openrouterModel.isEmpty(), "Settings must not default to a model name");
        QVERIFY2(fresh.deepseekModel.isEmpty(), "Settings must not default to a model name");
        QVERIFY2(fresh.kiloModel.isEmpty(), "Settings must not default to a model name");
        QVERIFY2(fresh.acpModel.isEmpty(), "Settings must not default to a model name");
        QVERIFY2(fresh.opencodeModel.isEmpty(), "Settings must not default to a model name");
    }

    void openCodeIsAProvider()
    {
        QCOMPARE(providerId(Provider::OpenCode), u"opencode"_s);
        QCOMPARE(providerFromId(u"opencode"_s), Provider::OpenCode);
        QVERIFY(!providerLabel(Provider::OpenCode).isEmpty());

        // Documented endpoint: opencode.ai serves its curated catalogue from
        // /zen/v1, which is also where the model list is fetched from.
        QCOMPARE(providerBaseUrl(Provider::OpenCode), u"https://opencode.ai/zen/v1"_s);

        Settings settings;
        settings.provider = Provider::OpenCode;
        settings.opencodeUrl.clear();
        QCOMPARE(providerBaseUrl(settings), u"https://opencode.ai/zen/v1"_s);
        settings.opencodeUrl = u"http://127.0.0.1:1234/v1"_s;
        QCOMPARE(providerBaseUrl(settings), u"http://127.0.0.1:1234/v1"_s);

        settings.opencodeApiKey = u"test-key"_s;
        QCOMPARE(apiKeyFor(settings), u"test-key"_s);
        settings.opencodeModel = u"gpt-5.5"_s;
        QCOMPARE(modelFor(settings), u"gpt-5.5"_s);

        // It is OpenAI-compatible, so its catalogue can be listed.
        QVERIFY(providerSupportsModelListing(Provider::OpenCode));
    }

    void everyProviderRoundTripsThroughItsId()
    {
        const QList<Provider> all = {Provider::Grok,
                                     Provider::OpenAI,
                                     Provider::OpenRouter,
                                     Provider::DeepSeek,
                                     Provider::OpenAICompatible,
                                     Provider::ClaudeCompatible,
                                     Provider::Kilo,
                                     Provider::Acp,
                                     Provider::OpenCode};
        for (const Provider provider : all) {
            const QString id = providerId(provider);
            QVERIFY(!id.isEmpty());
            QCOMPARE(providerFromId(id), provider);
            QVERIFY(!providerBaseUrl(provider).isEmpty());
            QVERIFY(!providerLabel(provider).isEmpty());
        }
    }

    void eachProviderHasItsOwnKeyAndModelSlot()
    {
        // A provider sharing another provider's slot is a silent bug: you set
        // the key and the model never reaches the wire.
        Settings settings;
        settings.openaiApiKey = u"a"_s;
        settings.openrouterApiKey = u"b"_s;
        settings.opencodeApiKey = u"c"_s;
        settings.openaiModel = u"m1"_s;
        settings.openrouterModel = u"m2"_s;
        settings.opencodeModel = u"m3"_s;

        settings.provider = Provider::OpenAI;
        QCOMPARE(apiKeyFor(settings), u"a"_s);
        QCOMPARE(modelFor(settings), u"m1"_s);
        settings.provider = Provider::OpenRouter;
        QCOMPARE(apiKeyFor(settings), u"b"_s);
        QCOMPARE(modelFor(settings), u"m2"_s);
        settings.provider = Provider::OpenCode;
        QCOMPARE(apiKeyFor(settings), u"c"_s);
        QCOMPARE(modelFor(settings), u"m3"_s);
    }

    void acpHasNoCatalogueEndpoint()
    {
        // ACP agents advertise themselves, so there is nothing to fetch and
        // the agent must not try.
        QVERIFY(!providerSupportsModelListing(Provider::Acp));
        QVERIFY(providerSupportsModelListing(Provider::OpenAI));
        QVERIFY(providerSupportsModelListing(Provider::OpenRouter));
    }

    void pickerSurfacesConfiguredAcpModelWithoutCatalogue()
    {
        Settings settings;
        settings.provider = Provider::Acp;
        settings.acpApiKey = u"acp-key"_s;
        settings.acpModel = u"workspace-agent"_s;

        QCOMPARE(pickerModelsFor(settings, Provider::Acp, {}),
                 QStringList{u"workspace-agent"_s});

        const QStringList catalog{u"other"_s, u"workspace-agent"_s};
        QCOMPARE(pickerModelsFor(settings, Provider::Acp, catalog), catalog);

        const QStringList withoutConfigured{u"alpha"_s, u"beta"_s};
        QCOMPARE(pickerModelsFor(settings, Provider::Acp, withoutConfigured),
                 (QStringList{u"workspace-agent"_s, u"alpha"_s, u"beta"_s}));

        settings.acpModel.clear();
        QVERIFY(pickerModelsFor(settings, Provider::Acp, {}).isEmpty());
    }

    void planParsingTerminatesOnATrailingLine()
    {
        // parsePlanFromText() used to spin forever once the plan section ended:
        // the final line was processed, `i` was never advanced past the end of
        // the text, and the loop re-entered on the same empty segment for as
        // long as fewer than 20 steps had been parsed.
        const QJsonArray noNewline = parsePlanFromText(u"Plan:\n1. Read the file\n2. Fix the bug"_s);
        QCOMPARE(noNewline.size(), 2);
        QCOMPARE(noNewline.at(0).toObject().value(u"description"_s).toString(), u"Read the file"_s);
        QCOMPARE(noNewline.at(1).toObject().value(u"description"_s).toString(), u"Fix the bug"_s);

        const QJsonArray withNewline = parsePlanFromText(u"Plan:\n1. Read the file\n2. Fix the bug\n"_s);
        QCOMPARE(withNewline.size(), 2);

        // A single step is enough to trigger the hang.
        const QJsonArray single = parsePlanFromText(u"Steps:\n- Do it"_s);
        QCOMPARE(single.size(), 1);

        // No plan heading means no plan, and no loop.
        QVERIFY(parsePlanFromText(u"Here is the answer."_s).isEmpty());

        // Steps stay capped so a runaway reply cannot grow the checklist.
        QString many = u"Plan:\n"_s;
        for (int i = 0; i < 40; ++i) {
            many += u"%1. step %2\n"_s.arg(i + 1).arg(i);
        }
        QCOMPARE(parsePlanFromText(many).size(), 20);
    }

    void planMergeKeepsIdsStable()
    {
        const QJsonArray plan = parsePlanFromText(u"Plan:\n1. one\n2. two"_s);
        const QJsonArray extended = mergePlanIntoAssistantMessage(plan, u"Plan:\n1. one\n2. two\n3. three"_s);
        QCOMPARE(extended.size(), 3);
        QCOMPARE(extended.at(0).toObject().value(u"id"_s).toString(), u"step1"_s);
        QCOMPARE(extended.at(2).toObject().value(u"description"_s).toString(), u"three"_s);
    }

    void acpNativeIsStdioTransport()
    {
        Settings settings;
        settings.provider = Provider::Acp;
        QCOMPARE(settings.apiFormat, ApiFormat::AcpNative);
        QVERIFY(usesAcpNative(settings));
        QVERIFY(!providerRequiresApiKey(settings, Provider::Acp));
        QVERIFY(providerIsSelectable(settings, Provider::Acp));
        QCOMPARE(settings.acpAgentId, u"grok-build"_s);
        QCOMPARE(settings.acpCommand, u"grok"_s);
        QCOMPARE(settings.acpArgs, u"agent stdio"_s);
        QCOMPARE(providerLabel(Provider::Acp), u"ACP"_s);
        QCOMPARE(acpAgentDisplayName(settings), u"Grok Build"_s);
        QCOMPARE(acpAgentPreset(u"gemini"_s).args, u"--acp"_s);
        QCOMPARE(acpAgentIdMatching(u"goose"_s, u"acp"_s), u"goose"_s);
        QCOMPARE(acpAgentIdMatching(u"python3"_s, u"agent.py"_s), u"custom"_s);

        settings.apiFormat = ApiFormat::OpenAICompatible;
        QVERIFY(!usesAcpNative(settings));
        QVERIFY(providerRequiresApiKey(settings, Provider::Acp));
        QCOMPARE(acpAgentDisplayName(settings), u"ACP"_s);
    }

    void installedAgentIsSelectableAndKeepsItsId()
    {
        // Agents installed from the ACP registry get ids the preset list does not
        // know ("opencode-v2" is not "opencode"). The config page used to fall
        // back to "custom" for them, which both hid the running agent from the
        // combo and showed the *custom* cache — a list of free models only — in
        // the model picker, even though the account was subscribed.
        Settings settings;
        settings.provider = Provider::Acp;

        QJsonArray installed;
        QJsonObject opencode;
        opencode.insert(u"id"_s, u"opencode-v2"_s);
        opencode.insert(u"name"_s, u"OpenCode V2"_s);
        opencode.insert(u"command"_s, u"/opt/kateai/acp-agents/opencode-v2/opencode"_s);
        opencode.insert(u"args"_s, QJsonArray{u"acp"_s});
        installed.append(opencode);
        // grok-build is both installed and a preset: the preset entry must win,
        // otherwise the combo would list the same agent twice.
        QJsonObject grok;
        grok.insert(u"id"_s, u"grok-build"_s);
        grok.insert(u"name"_s, u"Grok Build"_s);
        grok.insert(u"command"_s, u"npx"_s);
        installed.append(grok);
        settings.acpInstalledAgents =
            QString::fromUtf8(QJsonDocument(installed).toJson(QJsonDocument::Compact));

        const QList<AcpAgentPreset> choices = acpAgentChoices(settings);
        QStringList ids;
        for (const AcpAgentPreset &choice : choices) {
            ids.append(choice.id);
        }

        QVERIFY2(ids.contains(u"opencode-v2"_s),
                 "installed agent missing from the ACP Agent choices");
        QCOMPARE(ids.count(u"grok-build"_s), 1);
        // Custom stays selectable and stays last, so it is never the default.
        QCOMPARE(ids.count(u"custom"_s), 1);
        QCOMPARE(ids.constLast(), u"custom"_s);

        // The installed agent resolves to the registry name and launch line, so
        // selecting it does not wipe the command fields.
        const AcpAgentPreset launch = acpAgentLaunchLine(settings, u"opencode-v2"_s);
        QCOMPARE(launch.label, u"OpenCode V2"_s);
        QCOMPARE(launch.command, u"/opt/kateai/acp-agents/opencode-v2/opencode"_s);
        QCOMPARE(launch.args, u"acp"_s);
        QCOMPARE(acpAgentDisplayName(settings), u"Grok Build"_s);

        // An agent known to neither keeps an empty launch line: the typed
        // command/args must not be overwritten by it.
        settings.acpAgentId = u"something-new"_s;
        QVERIFY(acpAgentLaunchLine(settings, u"something-new"_s).command.isEmpty());
    }

    void installedAgentModelsAreReadFromItsOwnCacheKey()
    {
        // The picker reads the cache under the agent id, so an installed agent
        // must be looked up under its own key and never under "custom".
        Settings settings;
        QJsonArray installed;
        QJsonObject opencode;
        opencode.insert(u"id"_s, u"opencode-v2"_s);
        opencode.insert(u"name"_s, u"OpenCode V2"_s);
        installed.append(opencode);
        settings.acpInstalledAgents =
            QString::fromUtf8(QJsonDocument(installed).toJson(QJsonDocument::Compact));
        settings.acpAgentModels = u"{\"custom\":[\"opencode/free-only\"],"
                                  "\"opencode-v2\":[\"opencode/free\",\"opencode-go/paid\"]}"_s;

        const QStringList models = acpAgentAvailableModels(settings, u"opencode-v2"_s);
        QCOMPARE(models, (QStringList{u"opencode/free"_s, u"opencode-go/paid"_s}));
    }
};

QTEST_GUILESS_MAIN(TestProviders)
#include "test_providers.moc"

#include "contextmanager.h"

#include <QTest>

using namespace Qt::Literals::StringLiterals;
using namespace KateAi;

class TestContextManager : public QObject
{
    Q_OBJECT

private:
    static ChatMessage system(const QString &text)
    {
        ChatMessage m;
        m.role = ChatMessage::Role::System;
        m.content = text;
        return m;
    }
    static ChatMessage user(const QString &text)
    {
        ChatMessage m;
        m.role = ChatMessage::Role::User;
        m.content = text;
        return m;
    }
    static ChatMessage assistant(const QString &text)
    {
        ChatMessage m;
        m.role = ChatMessage::Role::Assistant;
        m.content = text;
        return m;
    }
    static ChatMessage toolCall(const QString &name, const QString &path)
    {
        ChatMessage m;
        m.role = ChatMessage::Role::Assistant;
        m.toolCalls.append(QJsonObject{{QStringLiteral("id"), QStringLiteral("c1")},
                                       {QStringLiteral("function"),
                                        QJsonObject{{QStringLiteral("name"), name},
                                                    {QStringLiteral("arguments"),
                                                     QJsonObject{{QStringLiteral("path"), path}}}}}});
        return m;
    }
    static ChatMessage toolResult(const QString &text)
    {
        ChatMessage m;
        m.role = ChatMessage::Role::Tool;
        m.toolCallId = QStringLiteral("c1");
        m.content = text;
        return m;
    }
    // The shape the agent loop actually records: the arguments as they went
    // over the wire, i.e. JSON text. Reading that text as an object always
    // yields an empty one, which silently dropped the file from the summary.
    static ChatMessage toolCallWithTextArguments(const QString &name, const QString &path)
    {
        ChatMessage m;
        m.role = ChatMessage::Role::Assistant;
        m.toolCalls.append(QJsonObject{{QStringLiteral("id"), QStringLiteral("c1")},
                                       {QStringLiteral("function"),
                                        QJsonObject{{QStringLiteral("name"), name},
                                                    {QStringLiteral("arguments"),
                                                     QStringLiteral("{\"path\":\"%1\"}").arg(path)}}}});
        return m;
    }
    // A conversation long enough to force compaction.
    static QList<ChatMessage> longHistory(int turns)
    {
        QList<ChatMessage> history;
        history << system(QStringLiteral("You are a helpful agent."));
        for (int i = 0; i < turns; ++i) {
            history << user(QStringLiteral("Request number %1: please do the thing for component %1.").arg(i));
            history << toolCall(QStringLiteral("edit_file"), QStringLiteral("src/file%1.cpp").arg(i));
            history << toolResult(QStringLiteral("Edited file%1. %1").arg(i).repeated(40));
        }
        history << user(QStringLiteral("And finally, summarise everything."));
        return history;
    }

private Q_SLOTS:
    void tokenEstimateIsRoughButOrdered()
    {
        QVERIFY(ContextManager::estimateTokens(QString()) == 0);
        QVERIFY(ContextManager::estimateTokens(QStringLiteral("a")) >= 1);
        QVERIFY(ContextManager::estimateTokens(QString(400, QLatin1Char('x')))
                > ContextManager::estimateTokens(QString(40, QLatin1Char('x'))));
    }

    void contextWindowFallsBackWithoutAModelNameTable()
    {
        // Deliberately no per-model table any more: it went stale on every
        // model release and could not know about new ones. Every name must now
        // return the same safe default, which is what settings.contextWindow or
        // the provider catalogue overrides.
        const int fallback = ContextManager::contextWindowFor(QStringLiteral("anything"));
        QVERIFY(fallback > 0);
        for (const QString &name : {QStringLiteral("gpt-4o-mini"), QStringLiteral("claude-sonnet-4-5"),
                                    QStringLiteral("grok-4.5"), QStringLiteral("some-unreleased-model")}) {
            QCOMPARE(ContextManager::contextWindowFor(name), fallback);
        }
        QCOMPARE(ContextManager::contextWindowFor(QString()), fallback);
    }

    void shortConversationIsSentUntouched()
    {
        QList<ChatMessage> history;
        history << system(QStringLiteral("system"));
        history << user(QStringLiteral("hello"));
        history << assistant(QStringLiteral("hi"));

        ContextManager::Options options;
        options.contextWindow = 200000;
        const auto result = ContextManager::build(history, options);
        // Compacting a conversation that fits throws detail away for nothing.
        QCOMPARE(result.size(), history.size());
        QCOMPARE(result.at(1).content, QStringLiteral("hello"));
    }

    void longConversationIsCompactedIntoBudget()
    {
        ContextManager::Options options;
        options.contextWindow = 8192;
        options.reserveForResponse = 2048;
        options.keepRecentTokens = 1500;
        const auto result = ContextManager::build(longHistory(40), options);

        QVERIFY(result.size() < 40 * 3);
        QVERIFY(ContextManager::estimateTokens(result)
                <= options.contextWindow - options.reserveForResponse);
    }

    void summaryPreservesUserIntentAndFiles()
    {
        ContextManager::Options options;
        options.contextWindow = 8192;
        options.reserveForResponse = 2048;
        options.keepRecentTokens = 1200;
        const auto result = ContextManager::build(longHistory(40), options);

        QString joined;
        for (const ChatMessage &m : result) {
            joined += m.content + QLatin1Char('\n');
        }
        QVERIFY2(joined.contains(ContextManager::summaryHeader()),
                 "the compacted span must be marked, or the model reads it as real history");
        // The oldest request and an early file must both survive.
        QVERIFY(joined.contains(QStringLiteral("Request number 0")));
        QVERIFY(joined.contains(QStringLiteral("src/file0.cpp")));
    }

    void summaryPreservesFilesWhenArgumentsAreJsonText()
    {
        QList<ChatMessage> history;
        history << system(QStringLiteral("system"));
        for (int i = 0; i < 40; ++i) {
            history << user(QStringLiteral("Request number %1: please do the thing for component %1.").arg(i));
            history << toolCallWithTextArguments(QStringLiteral("edit_file"), QStringLiteral("src/file%1.cpp").arg(i));
            history << toolResult(QStringLiteral("Edited file%1. %1").arg(i).repeated(40));
        }
        history << user(QStringLiteral("And finally, summarise everything."));

        ContextManager::Options options;
        options.contextWindow = 8192;
        options.reserveForResponse = 2048;
        options.keepRecentTokens = 1200;
        const auto result = ContextManager::build(history, options);

        QString joined;
        for (const ChatMessage &m : result) {
            joined += m.content + QLatin1Char('\n');
        }
        QVERIFY2(joined.contains(QStringLiteral("src/file0.cpp")),
                 "the tool call's arguments are JSON text; the path must still reach the summary");
    }

    void toolCallsAreNeverSplitFromResults()
    {
        ContextManager::Options options;
        options.contextWindow = 8192;
        options.reserveForResponse = 2048;
        // A range of tail sizes, because the cut point moves with them.
        for (int keep : {300, 700, 1200, 2500, 4000, 6000}) {
            options.keepRecentTokens = keep;
            const auto result = ContextManager::build(longHistory(40), options);
            // Every Tool message must be preceded by the assistant turn that
            // issued its call; an orphan makes providers reject the request.
            for (int i = 0; i < result.size(); ++i) {
                if (result.at(i).role != ChatMessage::Role::Tool) {
                    continue;
                }
                QVERIFY2(i > 0, "a tool result with nothing before it");
                const ChatMessage &previous = result.at(i - 1);
                const bool issuedCall = previous.role == ChatMessage::Role::Assistant
                    && !previous.toolCalls.isEmpty();
                QVERIFY2(issuedCall, "orphaned tool result in the compacted history");
            }
        }
    }

    void systemPromptIsNeverCompacted()
    {
        ContextManager::Options options;
        options.contextWindow = 4096;
        options.reserveForResponse = 1024;
        options.keepRecentTokens = 500;
        const auto result = ContextManager::build(longHistory(40), options);
        QVERIFY(!result.isEmpty());
        QCOMPARE(result.first().role, ChatMessage::Role::System);
        QVERIFY(result.first().content.contains(QStringLiteral("helpful agent")));
    }

    void lastUserMessageIsAlwaysKept()
    {
        ContextManager::Options options;
        options.contextWindow = 4096;
        options.reserveForResponse = 1024;
        options.keepRecentTokens = 200;
        const auto result = ContextManager::build(longHistory(40), options);
        QVERIFY(!result.isEmpty());
        QCOMPARE(result.last().content, QStringLiteral("And finally, summarise everything."));
    }

    void rejectedToolCallsAreFlagged()
    {
        QList<ChatMessage> history;
        history << system(QStringLiteral("sys"));
        for (int i = 0; i < 30; ++i) {
            history << user(QStringLiteral("do %1").arg(i));
            history << assistant(QStringLiteral("ok"));
        }
        ChatMessage rejected;
        rejected.role = ChatMessage::Role::Tool;
        rejected.toolCallId = QStringLiteral("c9");
        rejected.content = QStringLiteral("Tool rejected: edit_file was blocked.");
        history << rejected;
        history << user(QStringLiteral("carry on"));

        ContextManager::Options options;
        options.contextWindow = 4096;
        options.reserveForResponse = 1024;
        options.keepRecentTokens = 200;
        const auto result = ContextManager::build(history, options);
        QString joined;
        for (const ChatMessage &m : result) {
            joined += m.content + QLatin1Char('\n');
        }
        // Otherwise the model assumes the rejected edit landed.
        QVERIFY2(joined.contains(QStringLiteral("rejected")), "a rejected edit must be called out");
    }

    void emptyAndTinyInputsAreSafe()
    {
        ContextManager::Options options;
        QVERIFY(ContextManager::build({}, options).isEmpty());
        const auto one = ContextManager::build({user(QStringLiteral("hi"))}, options);
        QCOMPARE(one.size(), 1);
    }

    void noMessageCountCapDropsHistoryThatFits()
    {
        // A conversation that fits the window is sent whole. There is no
        // parallel "max messages" cutoff that would drop prompting mid-task.
        ContextManager::Options options;
        options.contextWindow = 200000;
        options.reserveForResponse = 1024;
        const auto history = longHistory(8);
        const auto result = ContextManager::build(history, options);
        QCOMPARE(result.size(), history.size());
        QCOMPARE(result.last().content, QStringLiteral("And finally, summarise everything."));
    }

    void tinyWindowStillKeepsTheLatestUser()
    {
        ContextManager::Options options;
        options.contextWindow = 2048;
        options.reserveForResponse = 512;
        options.keepRecentTokens = 200;
        options.compactionLevel = 3;
        const auto result = ContextManager::build(longHistory(40), options);
        QVERIFY(!result.isEmpty());
        QVERIFY(ContextManager::estimateTokens(result)
                <= options.contextWindow - options.reserveForResponse);
        bool sawLatest = false;
        for (const ChatMessage &m : result) {
            if (m.content.contains(QStringLiteral("And finally, summarise everything."))) {
                sawLatest = true;
                break;
            }
        }
        QVERIFY2(sawLatest, "compaction must not drop the live user request");
    }

    void extraCompactionPressureShrinksFurther()
    {
        ContextManager::Options mild;
        mild.contextWindow = 8192;
        mild.reserveForResponse = 2048;
        mild.keepRecentTokens = 4000;
        mild.compactionLevel = 0;
        ContextManager::Options hard = mild;
        hard.compactionLevel = 4;
        const auto history = longHistory(40);
        const auto mildResult = ContextManager::build(history, mild);
        const auto hardResult = ContextManager::build(history, hard);
        QVERIFY(ContextManager::estimateTokens(hardResult)
                <= ContextManager::estimateTokens(mildResult));
        QVERIFY(ContextManager::estimateTokens(hardResult)
                <= hard.contextWindow - hard.reserveForResponse);
    }

    // --- reset ---------------------------------------------------------------

    void resetFoldsEverythingIntoOneSummary()
    {
        ContextManager::Options options;
        options.contextWindow = 8192;
        options.reserveForResponse = 2048;
        options.keepRecentTokens = 4000;
        const auto history = longHistory(40);
        const auto result = ContextManager::resetContext(history, options);

        // Everything but the system prompt, the summary and the live turn is
        // gone: a reset that leaves 40 turns behind has reclaimed nothing.
        QVERIFY(result.size() < history.size() / 3);
        QCOMPARE(result.first().role, ChatMessage::Role::System);
        QCOMPARE(result.last().content, QStringLiteral("And finally, summarise everything."));

        bool sawSummary = false;
        for (const ChatMessage &m : result) {
            if (m.content.startsWith(ContextManager::summaryHeader())) {
                sawSummary = true;
                break;
            }
        }
        QVERIFY2(sawSummary, "the reset must be marked, or the model reads it as real history");
    }

    void resetKeepsWhatMattered()
    {
        ContextManager::Options options;
        options.contextWindow = 8192;
        options.reserveForResponse = 2048;
        const auto result = ContextManager::resetContext(longHistory(40), options);

        QString joined;
        for (const ChatMessage &m : result) {
            joined += m.content + QLatin1Char('\n');
        }
        // The requests, the files touched and the tools used all have to
        // survive the fold: they are what makes the summary worth keeping.
        QVERIFY(joined.contains(QStringLiteral("Request number 0")));
        QVERIFY(joined.contains(QStringLiteral("src/file0.cpp")));
        QVERIFY(joined.contains(QStringLiteral("edit_file")));
    }

    void resetIsSmallerThanTheHistoryItReplaces()
    {
        ContextManager::Options options;
        options.contextWindow = 8192;
        options.reserveForResponse = 2048;
        const auto history = longHistory(40);
        const auto result = ContextManager::resetContext(history, options);
        // A window this full only needs a fraction of it back; otherwise the
        // reset does not do the one job it exists for.
        QVERIFY(ContextManager::estimateTokens(result)
                < ContextManager::estimateTokens(history) / 2);
        QVERIFY(ContextManager::estimateTokens(result) <= options.contextWindow - options.reserveForResponse);
    }

    void resetLeavesAConversationItCannotShrink()
    {
        ContextManager::Options options;
        options.contextWindow = 8192;
        QList<ChatMessage> history;
        history << system(QStringLiteral("sys"));
        history << user(QStringLiteral("hello"));
        const auto result = ContextManager::resetContext(history, options);
        QCOMPARE(result.size(), history.size());
        QCOMPARE(result.at(1).content, QStringLiteral("hello"));
    }
};

